Кури конфиг nginx /etc/nginx/conf.d/default.conf<br />
Вот пример моего, не полный, ибо незачем палить все.😉<br />
<pre class="xfBb-code" data-lang="">server {
    root /var/www/твоя папка сайта;
    index index.php;
    server_name твой домен www.твой домен;
    charset utf8;

    error_log /var/log/nginx/название твоего лога для сайта.log;
    access_log off;

    location ~ \.php$ {
        fastcgi_pass 127.0.0.1:9000;
        fastcgi_index index.php;
        include fastcgi_params;
    }

        # Cached Images
        location ~* \.(jpg|jpeg|gif|png|css|js|ico)$ {
            root        /var/www/твоя папка сайта;
            access_log  off;
            expires      30d;
            add_header  Cache-Control  public;
        }

        location ~ \/admin|backup\/ {
            deny all;
        }
        # Deny folder (Sec. lvl1)
        location ~ \/(cache|log|attach_mod|cache|config|includes|language|triggers)\/ {
            deny all;
        }

        # deny access to .htaccess files, if Apache&#039;s document root
        # concurs with nginx&#039;s one
        # deny sql,tpl,db,inc,log
        location ~ /\.ht {
            deny  all;
        }
        location ~ \.(.*sql|tpl|db|inc|log)$ {
            deny  all;
        }

    }</pre>
